$\gamma_e(0) = 0$, for every $\kappa$ and every $e$.
  \begin{proof}

    Both summands are $\arcsin 0 = 0$.
  \end{proof}

If $\kappa_e, \kappa_{e+1} > 0$ and $0 < \beta < U_e$ then
  $0 < \mathrm{gapLength}\,\kappa\,e\,\beta < C_e$.
  \begin{proof}

    This is the other defining property of the element chosen in
    \cref{def:gap_length}.
  \end{proof}

Assume $\kappa_e, \kappa_{e+1} > 0$ and set $r_i = 1/\kappa_i$. Then
  \[
    U_e = \frac{\pi}{2} + \arcsin\frac{\min(r_e,\, r_{e+1})}
                                      {\max(r_e,\, r_{e+1})} .
  \]
  \begin{proof}

    Inversion is order-reversing on $(0,\infty)$, so
    $\min(r_e,r_{e+1}) = 1/\max(\kappa_e,\kappa_{e+1})$ and
    $\max(r_e,r_{e+1}) = 1/\min(\kappa_e,\kappa_{e+1})$. Hence
    \[
      \frac{\min(r_e,r_{e+1})}{\max(r_e,r_{e+1})}
        = \frac{1/\max(\kappa_e,\kappa_{e+1})}{1/\min(\kappa_e,\kappa_{e+1})}
        = \frac{\min(\kappa_e,\kappa_{e+1})}{\max(\kappa_e,\kappa_{e+1})},
    \]
    so the two expressions for $U_e$ agree term by term.
  \end{proof}
